 c={'id':'business_'+str(len(cs)+1).zfill(3),'field':'business_management','form_id':form,'title':title,'authors':au,'year':y,'venue':m.get('container-title',[''])[0],'doi':doi,'doi_aliases':[m['DOI']] if m['DOI'].lower()!=doi.lower() else [],'stable_url':pub,'volume':m.get('volume'),'issue':m.get('issue'),'pages':m.get('page'),'form_basis':basis,'form_status':'publisher abstract supports placement','selection_signal_type':'publisher editorial selection','selection_evidence':'Peer-reviewed individual article selected for relevance to underrepresented management form; no claim of high citation or readership.','selection_source_url':pub,'citation_count':None,'citation_provider':None,'citation_snapshot':None,'verification_status':'Crossref live metadata and publisher abstract','verification_sources':[{'provider':'Crossref','query_url':u,'retrieved_at':now},{'provider':'publisher','query_url':pub,'retrieved_at':now}],'date_notes':'2015–2019 supplement','copy_status':'complete copy not requested or verified','retrieval_locator':f"{title}; {', '.join(au)}; {m.get('container-title',[''])[0]}, {y}; DOI {doi}",'why_this_example':basis,'limitations':'Not established highly cited or widely read; publisher journal selection is the available notability signal. Full text not inspected.'};cs.append(c)
 cell=next(x for x in cells if x['form_id']==form);cell['candidate_ids'].append(c['id']);cell['provided']+=1;cell['status']='partial_gap';cell['reason']='Applicable: one 2015–2019 supplemental example identified; two further historical targets remain.'
